// Variables and secrets of the Worker (#18; implementation decision R12).
// They are declared here, not generated by `wrangler types`, so the
// generated file never depends on a local `.dev.vars`. Local values go in
// `.dev.vars` (see `.dev.vars.example`); deployed values are Worker
// variables and secrets.
// `STORY_RUN` comes from `wrangler types`, typed from `StoryRunWorkflow`.
interface StoryRunEnv {
  OPENAI_BASE_URL: string;
  OPENAI_API_KEY: string;
  MODEL_SCRIPT: string;
  MODEL_SCENE: string;
  MODEL_TTS: string;
  TTS_BASE_URL: string;
  TTS_API_KEY: string;
  TTS_VOICE: string;
  AI_GATEWAY_TOKEN?: string;
  // "stub" gives the default stub model; any other value, the real client.
  MODEL_MODE?: "real" | "stub";
}

// The generated global `Env` and `Cloudflare.Env` both extend
// `__BaseEnv_Env`, so both get the fields.
declare namespace Cloudflare {
  interface Env extends StoryRunEnv {}
}
interface Env extends StoryRunEnv {}
